// @ts-check
import { randomUUID } from "node:crypto";
import { mkdir, unlink, writeFile } from "node:fs/promises";
import path from "node:path";
import { execute } from "@dwtechs/antity-pgsql";
import { log } from "@dwtechs/winstan";
import { PUBLIC_ROOT } from "../web/engine.js";

/** Served by the `${WEB_MOUNT}/assets/branding` static mount in app.js. */
export const LOGO_DIR = path.join(PUBLIC_ROOT, "assets", "branding");

/** Only names generated by `saveLogo` are ever read back, deleted or exposed. */
export const LOGO_FILE_RE = /^logo-[0-9a-f-]{36}\.(png|jpg|webp|svg)$/;

/** Same guarantee for names generated by `saveFavicon`. */
export const FAVICON_FILE_RE = /^favicon-[0-9a-f-]{36}\.(png|jpg|webp|svg)$/;

// Column names are constants, never request input, so they are safe to inline in SQL.
const KINDS = Object.freeze({
  logo: {
    prefix: "logo",
    fileCol: "logoFile",
    urlCol: "logoUrl",
    re: LOGO_FILE_RE,
  },
  favicon: {
    prefix: "favicon",
    fileCol: "faviconFile",
    urlCol: "faviconUrl",
    re: FAVICON_FILE_RE,
  },
});

/**
 * Stores the image on disk, points the branding row at it (clearing the URL
 * column, the either/or alternative) and drops the previous file. The
 * client-supplied filename is never used.
 *
 * @param {keyof typeof KINDS} kind
 * @param {number} id branding row id
 * @param {{ userId: number, nickname: string }} consumer
 * @param {{ buffer: Buffer, ext: string }} image
 * @returns {Promise<Record<string, unknown>|null>} updated row, or null when the row is missing/archived
 */
async function saveImage(kind, id, consumer, image) {
  const { prefix, fileCol, urlCol, re } = KINDS[kind];
  const file = `${prefix}-${randomUUID()}.${image.ext}`;
  if (!re.test(file)) throw new Error(`Invalid ${kind} extension`);
  await mkdir(LOGO_DIR, { recursive: true });
  await writeFile(path.join(LOGO_DIR, file), image.buffer, { flag: "wx" });

  try {
    // The CTE reads the pre-update value, so one statement yields both the new row and the old file name.
    const res = await execute(
      `WITH old AS (
         SELECT "${fileCol}" AS previous FROM branding
         WHERE id = $4 AND archived IS NOT TRUE
       )
       UPDATE branding
       SET "${fileCol}" = $1, "${urlCol}" = '', "updatedAt" = NOW(),
           "updaterId" = $2, "updaterName" = $3
       WHERE id = $4 AND archived IS NOT TRUE
       RETURNING *, (SELECT previous FROM old) AS "previousFile"`,
      [file, consumer.userId, consumer.nickname, id],
      null,
    );
    const row = res.rows?.[0];
    if (!row) {
      await removeImage(file);
      return null;
    }
    const { previousFile, ...updated } = row;
    if (previousFile && previousFile !== file) await removeImage(previousFile);
    return updated;
  } catch (err) {
    await removeImage(file);
    throw err;
  }
}

/**
 * Clears the file column and removes the stored image from disk.
 *
 * @param {keyof typeof KINDS} kind
 * @param {number} id branding row id
 * @param {{ userId: number, nickname: string }} consumer
 * @returns {Promise<Record<string, unknown>|null>} updated row, or null when the row is missing/archived
 */
async function deleteImage(kind, id, consumer) {
  const { fileCol } = KINDS[kind];
  const res = await execute(
    `WITH old AS (
       SELECT "${fileCol}" AS previous FROM branding
       WHERE id = $3 AND archived IS NOT TRUE
     )
     UPDATE branding
     SET "${fileCol}" = '', "updatedAt" = NOW(),
         "updaterId" = $1, "updaterName" = $2
     WHERE id = $3 AND archived IS NOT TRUE
     RETURNING *, (SELECT previous FROM old) AS "previousFile"`,
    [consumer.userId, consumer.nickname, id],
    null,
  );
  const row = res.rows?.[0];
  if (!row) return null;
  const { previousFile, ...updated } = row;
  if (previousFile) await removeImage(previousFile);
  return updated;
}

/**
 * @param {number} id
 * @param {{ userId: number, nickname: string }} consumer
 * @param {{ buffer: Buffer, ext: string }} logo
 */
export const saveLogo = (id, consumer, logo) =>
  saveImage("logo", id, consumer, logo);

/**
 * @param {number} id
 * @param {{ userId: number, nickname: string }} consumer
 */
export const deleteLogo = (id, consumer) => deleteImage("logo", id, consumer);

/**
 * @param {number} id
 * @param {{ userId: number, nickname: string }} consumer
 * @param {{ buffer: Buffer, ext: string }} favicon
 */
export const saveFavicon = (id, consumer, favicon) =>
  saveImage("favicon", id, consumer, favicon);

/**
 * @param {number} id
 * @param {{ userId: number, nickname: string }} consumer
 */
export const deleteFavicon = (id, consumer) =>
  deleteImage("favicon", id, consumer);

/**
 * Best-effort delete: a leftover file is harmless, a failed request is not.
 * @param {string} file
 * @returns {Promise<void>}
 */
async function removeImage(file) {
  if (!LOGO_FILE_RE.test(file) && !FAVICON_FILE_RE.test(file)) return;
  try {
    await unlink(path.join(LOGO_DIR, file));
  } catch (err) {
    log.warn(`removeImage ${file} failed: ${err?.message || err}`);
  }
}
